import re
from importlib.metadata import version
from pathlib import Path

from ..client_interface import ClientInterface
from .pc_executor import PCExecutor
from .pyro_handle import PyroProxyHandle


class PyroClient(ClientInterface):
    def __init__(
        self,
        host,
        user,
        password,
        ssh_port=22,
        pyro_ip=None,
        pyro_port="9092",
        remote_dir="C:/rsi",
        python_path="python",
        upload=True,
    ):
        super().__init__()
        pyro_ip = host if pyro_ip is None else pyro_ip
        self._executor = PCExecutor(
            host=host,
            user=user,
            password=password,
            ssh_port=ssh_port,
            remote_dir=remote_dir,
            python_path=python_path,
            pyro_ip=pyro_ip,
            pyro_port=pyro_port,
        )
        self._host_id = f"{host}:{pyro_port}"
        self._version = version("taf.hw.rmod_serial_interface")
        self._server = PyroProxyHandle(uri=f"PYRO:RSI@{self._host_id}", version=self._version)
        self._with_upload = upload

    def setup(self, timeout=5):
        if self._with_upload:
            self._update_server_version_string()
            self._executor.scp_server_files()
        if not self._server.is_reachable():
            self._executor.run_server()
            self._server.wait_till_reachable(timeout)

    def _update_server_version_string(self):
        server_file = Path(__file__).parent / "pyro_server" / "server.py"
        if not server_file.exists():
            raise FileNotFoundError(f'Cannot set server version string; File "{server_file}" does not exist')
        if not server_file.is_file():
            raise FileNotFoundError(f'Cannot set server version string; File "{server_file}" is not a regular file')
        with server_file.open("r+") as f:
            content = f.read()
            new_content = re.sub(
                r"""^__version__ = ['"](\d+\.\d+\.\d+)['"]$""", rf'__version__ = "{self._version}"', content, flags=re.M
            )
            f.seek(0)
            f.write(new_content)
            f.truncate()

    def _setup_rmod_connection(self, login, password, port):
        return self.catch_remote_error(self._server.setup_rmod_connection)(login, password, port)

    def _setup_custom_rmod_connection(self, port, login, password, shell_prompt_regex):
        return self.catch_remote_error(self._server.setup_custom_rmod_connection)(
            port, login, password, shell_prompt_regex
        )

    def send_command(self, cmd, port, elevated=False, wait_echo=True):
        return self.catch_remote_error(self._server.send_command)(cmd, port, elevated, wait_echo)

    def execute_command(self, cmd, port, elevated=False, timeout=3, wait_echo=True):
        return self.catch_remote_error(self._server.execute_command)(cmd, port, elevated, timeout, wait_echo)

    def take_snapshot(self, port, timeout=180):
        return self.catch_remote_error(self._server.take_snapshot)(port, timeout)

    def collect_rmod_output(self, port):
        return self.catch_remote_error(self._server.collect_rmod_output)(port)

    def _teardown_rmod_connection(self, port):
        self.catch_remote_error(self._server.teardown_rmod_connection)(port)

    def shutdown(self):
        self._server.shutdown()
        self._used_rmods = []
        self._executor.join_server()

    def _download_log(self, local_path, port):
        logfile = self.catch_remote_error(self._server.get_session_log_path)(port)
        self._executor.download_log(local_path=local_path, remote_path=logfile)
        return local_path

    @staticmethod
    def catch_remote_error(subroutine):
        def wrapper(*args, **kwargs):
            ret_val, error = subroutine(*args, **kwargs)
            if error is not None:
                raise error
            return ret_val

        return wrapper

    def get_rmod_info(self, port):
        return self.catch_remote_error(self._server.get_rmod_info)(port)

    def set_rmod_credentials(self, port, login, password, shell_prompt_regex=None):
        return self.catch_remote_error(self._server.set_rmod_credentials)(port, login, password, shell_prompt_regex)
